(7291114, 1136680, 37858, '<td valign="top">Beautiful photograph.  Not sure I see Adams in it, though, that''s probably on me.</td>', 'Beautiful photograph.  Not sure I see Adams in it, though, that''s probably on me.', '2014-12-08 00:47:11.000000', NULL, 1),
(7291116, 1136657, 37858, '<td valign="top">Very Adamsesque and a beautiful image too.  Well done.</td>', 'Very Adamsesque and a beautiful image too.  Well done.', '2014-12-08 00:48:13.000000', NULL, 1),
