(7291161, 1136537, 54446, '<td valign="top">Beautiful tonal range.  Should ribbon.  My highest score.  Wonderful detail in shadows and highlights.  Excellent choice for this challenge because of elements of interest.</td>', 'Beautiful tonal range.  Should ribbon.  My highest score.  Wonderful detail in shadows and highlights.  Excellent choice for this challenge because of elements of interest.', '2014-12-08 05:36:05.000000', NULL, 1),
(7291212, 1136742, 54446, '<td valign="top">Seems to need a slight CW rotation.  Good job on the b&amp;w conversion.  From an AA perspective, he would not have photographed the human impact on the wilderness.</td>', 'Seems to need a slight CW rotation.  Good job on the b&w conversion.  From an AA perspective, he would not have photographed the human impact on the wilderness.', '2014-12-08 09:27:23.000000', NULL, 1),
(7291224, 1136598, 54446, '<td valign="top">Nice composition.  Good subject.  OK sky.  8</td>', 'Nice composition.  Good subject.  OK sky.  8', '2014-12-08 09:49:58.000000', NULL, 1),
