(7292656, 1136738, 13077, '<td valign="top">An interesting building, looks very old.</td>', 'An interesting building, looks very old.', '2014-12-14 12:37:21.000000', NULL, 1),
(7292657, 1136734, 13077, '<td valign="top">Great looking shapes/patterns, nice find.</td>', 'Great looking shapes/patterns, nice find.', '2014-12-14 12:37:50.000000', NULL, 1),
(7292659, 1136747, 13077, '<td valign="top">Nicely shot, cool how the clouds almost mirror the peaks.</td>', 'Nicely shot, cool how the clouds almost mirror the peaks.', '2014-12-14 12:38:26.000000', NULL, 1),
(7292660, 1136773, 13077, '<td valign="top">With a good sky like this, I think shooting just the tallest trees against the sky might have worked better. As it is, the foreground doesn''t offer much to the photo as a whole.</td>', 'With a good sky like this, I think shooting just the tallest trees against the sky might have worked better. As it is, the foreground doesn''t offer much to the photo as a whole.', '2014-12-14 12:39:17.000000', NULL, 1),
(7292661, 1136759, 13077, '<td valign="top">Nicely composed and has a classic look to it.</td>', 'Nicely composed and has a classic look to it.', '2014-12-14 12:39:41.000000', NULL, 1),
(7292663, 1136693, 13077, '<td valign="top">Good find - well positioned and good depth of field for an un-distracting background.</td>', 'Good find - well positioned and good depth of field for an un-distracting background.', '2014-12-14 12:41:19.000000', NULL, 1),
(7292664, 1136672, 13077, '<td valign="top">Very cool rock and sky. Nicely exposed and processed too.</td>', 'Very cool rock and sky. Nicely exposed and processed too.', '2014-12-14 12:42:55.000000', NULL, 1),
(7292665, 1136739, 13077, '<td valign="top">Great use of the wide angle perspective and the dramatic sky. Very well exposed and processed too.</td>', 'Great use of the wide angle perspective and the dramatic sky. Very well exposed and processed too.', '2014-12-14 12:43:29.000000', NULL, 1),
(7292666, 1136768, 13077, '<td valign="top">Very nice. Perfect way of showing a hot spring.</td>', 'Very nice. Perfect way of showing a hot spring.', '2014-12-14 12:44:11.000000', NULL, 1),
(7292667, 1136757, 13077, '<td valign="top">I like the processing, it pops nicely.</td>', 'I like the processing, it pops nicely.', '2014-12-14 12:44:47.000000', NULL, 1),
(7292668, 1136780, 13077, '<td valign="top">Very good detail, perfectly exposed and good depth of field all the way through the scene. I like it a lot.</td>', 'Very good detail, perfectly exposed and good depth of field all the way through the scene. I like it a lot.', '2014-12-14 12:45:49.000000', NULL, 1),
(7292669, 1136737, 13077, '<td valign="top">"who is it?...."</td>', '"who is it?...."', '2014-12-14 12:46:08.000000', NULL, 1),
(7292670, 1136761, 13077, '<td valign="top">I like the look of the water here, and the variety of trees/bushes.</td>', 'I like the look of the water here, and the variety of trees/bushes.', '2014-12-14 12:46:34.000000', NULL, 1),
(7292672, 1136694, 13077, '<td valign="top">Interesting study of shapes and tones</td>', 'Interesting study of shapes and tones', '2014-12-14 12:47:18.000000', NULL, 1),
(7292673, 1136748, 13077, '<td valign="top">I like this. It''s composed/cropped well, all the shapes play together nicely.</td>', 'I like this. It''s composed/cropped well, all the shapes play together nicely.', '2014-12-14 12:49:38.000000', NULL, 1),
(7292674, 1136763, 13077, '<td valign="top">I like the various spots of light where the sun shines through the clouds there. Nicely composed, and although it''s not bad in black and white this is one I have a feeling would look a lot better in color.</td>', 'I like the various spots of light where the sun shines through the clouds there. Nicely composed, and although it''s not bad in black and white this is one I have a feeling would look a lot better in color.', '2014-12-14 12:52:02.000000', NULL, 1),
(7292675, 1136680, 13077, '<td valign="top">A very tranquil and beautiful looking scene. Perfectly exposed, too.</td>', 'A very tranquil and beautiful looking scene. Perfectly exposed, too.', '2014-12-14 12:52:42.000000', NULL, 1),
(7292677, 1136771, 13077, '<td valign="top">I like the harsh lighting and choppy waters, well done keeping so much detail throughout. Nicely composed too, clean but visually striking.</td>', 'I like the harsh lighting and choppy waters, well done keeping so much detail throughout. Nicely composed too, clean but visually striking.', '2014-12-14 12:54:04.000000', NULL, 1),
(7292678, 1136657, 13077, '<td valign="top">Very cool. The sky looks awesome.</td>', 'Very cool. The sky looks awesome.', '2014-12-14 12:54:40.000000', NULL, 1),
(7292680, 1136660, 13077, '<td valign="top">Very dramatic weather conditions for this one - fog and dark looming clouds. Nicely shot and processed too.</td>', 'Very dramatic weather conditions for this one - fog and dark looming clouds. Nicely shot and processed too.', '2014-12-14 12:56:07.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7292681, 1136598, 13077, '<td valign="top">Very good detail in the rocks, and nicely positioned to have the brighter part of the sky behind the tree. Should do very well.</td>', 'Very good detail in the rocks, and nicely positioned to have the brighter part of the sky behind the tree. Should do very well.', '2014-12-14 12:56:44.000000', NULL, 1),
(7292682, 1136524, 13077, '<td valign="top">Looks like a nice place to live, but the photo is a bit soft and grainy, maybe the lighting was not enough for whatever camera was used.</td>', 'Looks like a nice place to live, but the photo is a bit soft and grainy, maybe the lighting was not enough for whatever camera was used.', '2014-12-14 12:57:31.000000', NULL, 1),
(7292683, 1136735, 13077, '<td valign="top">There''s something about the composition I''m not crazy about here, hard to put my finger on why... Might have to do with the sky, like maybe it should be more focused on the details in the ground and just have the sky at the top part of the frame.</td>', 'There''s something about the composition I''m not crazy about here, hard to put my finger on why... Might have to do with the sky, like maybe it should be more focused on the details in the ground and just have the sky at the top part of the frame.', '2014-12-14 12:58:55.000000', NULL, 1),
(7292684, 1136744, 13077, '<td valign="top">Interesting textures in the cliffside here.</td>', 'Interesting textures in the cliffside here.', '2014-12-14 13:00:42.000000', NULL, 1),
(7292685, 1136722, 13077, '<td valign="top">Very sharp and detailed in the foreground and I like the sort of leading line of the frozen water.</td>', 'Very sharp and detailed in the foreground and I like the sort of leading line of the frozen water.', '2014-12-14 13:01:27.000000', NULL, 1),
(7292687, 1136720, 13077, '<td valign="top">Nicely composed and an interesting, peaceful looking scene. I wonder if it would have been possible to keep some detail in the sky while keeping the same amount of detail in the darker parts? The textures of the land and the boats are the star here, but just curious.</td>', 'Nicely composed and an interesting, peaceful looking scene. I wonder if it would have been possible to keep some detail in the sky while keeping the same amount of detail in the darker parts? The textures of the land and the boats are the star here, but just curious.', '2014-12-14 13:02:37.000000', NULL, 1),
(7292689, 1136742, 13077, '<td valign="top">Yep, that''s the name of the website.</td>', 'Yep, that''s the name of the website.', '2014-12-14 13:03:13.000000', NULL, 1),
(7292691, 1136769, 13077, '<td valign="top">Good use of backlighting and well processed.</td>', 'Good use of backlighting and well processed.', '2014-12-14 13:03:37.000000', NULL, 1),
(7292692, 1136572, 13077, '<td valign="top">A lot of potential with this one, but I think a more simple (maybe more close up) composition could have been found and would have looked a bit better.</td>', 'A lot of potential with this one, but I think a more simple (maybe more close up) composition could have been found and would have looked a bit better.', '2014-12-14 13:04:16.000000', NULL, 1),
(7292694, 1136755, 13077, '<td valign="top">Very good detail in the leaves. Well arranged.</td>', 'Very good detail in the leaves. Well arranged.', '2014-12-14 13:04:41.000000', NULL, 1),
(7292696, 1136760, 13077, '<td valign="top">I think he would have eventually started shooting landscapes in color too.</td>', 'I think he would have eventually started shooting landscapes in color too.', '2014-12-14 13:06:23.000000', NULL, 1),
(7292697, 1136659, 13077, '<td valign="top">Well composed and I like the broken icy textures in the water. Good use of a pure white sky here, too.</td>', 'Well composed and I like the broken icy textures in the water. Good use of a pure white sky here, too.', '2014-12-14 13:07:00.000000', NULL, 1),
(7292698, 1136710, 13077, '<td valign="top">Nicely composed and processed. While it works pretty well in B&amp;W for the challenge, I have a feeling this would be stronger in color for use elsewhere.</td>', 'Nicely composed and processed. While it works pretty well in B&W for the challenge, I have a feeling this would be stronger in color for use elsewhere.', '2014-12-14 13:07:55.000000', NULL, 1),
(7292699, 1136750, 13077, '<td valign="top">Good use of light and contrast, and great details in the foreground snow drift.</td>', 'Good use of light and contrast, and great details in the foreground snow drift.', '2014-12-14 13:08:27.000000', NULL, 1),
(7292700, 1136715, 13077, '<td valign="top">I like it. Good composition to use all the angles and shapes.</td>', 'I like it. Good composition to use all the angles and shapes.', '2014-12-14 13:09:02.000000', NULL, 1),
(7292701, 1136516, 13077, '<td valign="top">The water looks very dramatic here - good use of high contrast, and well composed with the curve of the beach.</td>', 'The water looks very dramatic here - good use of high contrast, and well composed with the curve of the beach.', '2014-12-14 13:09:59.000000', NULL, 1),
(7292702, 1136740, 13077, '<td valign="top">A nice and simple shot, but either over processed/noise-reduced or something - lots of detail lost in the foreground trees.</td>', 'A nice and simple shot, but either over processed/noise-reduced or something - lots of detail lost in the foreground trees.', '2014-12-14 13:10:38.000000', NULL, 1),
(7292711, 1136595, 100831, '<td valign="top">Gorgeous scene and details... love the conversion with the dark blacks ... you and AA, both. know how to stop time, breathe, and take in the moment.</td>', 'Gorgeous scene and details... love the conversion with the dark blacks ... you and AA, both. know how to stop time, breathe, and take in the moment.', '2014-12-14 13:50:10.000000', NULL, 1),
(7292712, 1136659, 150277, '<td valign="top">Love the pattern and reflection in this.  I found your image very calming.</td>', 'Love the pattern and reflection in this.  I found your image very calming.', '2014-12-14 13:50:33.000000', NULL, 1),
(7292713, 1136660, 100831, '<td valign="top">oh beautiful, for spacious skies... the variety of tones in this image is astonishing.</td>', 'oh beautiful, for spacious skies... the variety of tones in this image is astonishing.', '2014-12-14 13:51:13.000000', NULL, 1),
(7292714, 1136748, 150277, '<td valign="top">Wow, very moving.  What a great compilation of lights and darks.</td>', 'Wow, very moving.  What a great compilation of lights and darks.', '2014-12-14 13:51:28.000000', NULL, 1),
(7292715, 1136680, 150277, '<td valign="top">I love this composition.</td>', 'I love this composition.', '2014-12-14 13:51:59.000000', NULL, 1),
(7292716, 1136750, 150277, '<td valign="top">Awwww, that poor little branch in front makes me so sad.  But beautiful image, lights and darks are very powerful.</td>', 'Awwww, that poor little branch in front makes me so sad.  But beautiful image, lights and darks are very powerful.', '2014-12-14 13:53:04.000000', NULL, 1),
(7292717, 1136672, 100831, '<td valign="top">King of the Hill... you/he caught my attention for sure... wonderful capture.</td>', 'King of the Hill... you/he caught my attention for sure... wonderful capture.', '2014-12-14 13:53:22.000000', NULL, 1),
(7292718, 1136564, 100831, '<td valign="top">amazing similarities don''t you think.</td>', 'amazing similarities don''t you think.', '2014-12-14 13:54:31.000000', NULL, 1),
(7292719, 1136734, 150277, '<td valign="top">What a great range in this image.  My eye was sure drawn all the way through this shot and landed back on those interesting roundish things.  (Are they roots, vegetables??)  I am mystified but sure found this image enjoyable.  And it seems perfect for the challenge.</td>', 'What a great range in this image.  My eye was sure drawn all the way through this shot and landed back on those interesting roundish things.  (Are they roots, vegetables??)  I am mystified but sure found this image enjoyable.  And it seems perfect for the challenge.', '2014-12-14 13:56:07.000000', NULL, 1),
(7292721, 1136537, 150277, '<td valign="top">Lovely.  Those hills in the background are just stunning with the bit of fog that seems to be rising.</td>', 'Lovely.  Those hills in the background are just stunning with the bit of fog that seems to be rising.', '2014-12-14 13:57:25.000000', NULL, 1),
(7292723, 1136734, 100831, '<td valign="top">This keeps my attention.... <br/>Love the abstractness, tones and details... not sure it needs a frame but that''s just me... let nature flow. 7 for now.</td>', 'This keeps my attention.... Love the abstractness, tones and details... not sure it needs a frame but that''s just me... let nature flow. 7 for now.', '2014-12-14 14:06:06.000000', NULL, 1),
(7292725, 1136745, 100831, '<td valign="top">Subtle contrasts, but it works better as I view it more... quite nice actually.. love the sprawling view. Bump.</td>', 'Subtle contrasts, but it works better as I view it more... quite nice actually.. love the sprawling view. Bump.', '2014-12-14 14:09:17.000000', NULL, 1),
(7292726, 1136745, 124982, '<td valign="top">Really love the scene, and the leading line of the road through the frame. I do wish there was a touch more contrast in the mountains though -- it''s all a little flat grey right now. A little richer blacks and this image would sing!</td>', 'Really love the scene, and the leading line of the road through the frame. I do wish there was a touch more contrast in the mountains though -- it''s all a little flat grey right now. A little richer blacks and this image would sing!', '2014-12-14 14:09:37.000000', NULL, 1),
(7292727, 1136659, 100831, '<td valign="top">Nice dark blacks and I love the reflection.</td>', 'Nice dark blacks and I love the reflection.', '2014-12-14 14:09:54.000000', NULL, 1),
(7292728, 1136767, 124982, '<td valign="top">Not quite what I relate with Ansel, but that''s okay...it''s an awesome shot. Love the detail and the rich contrast!</td>', 'Not quite what I relate with Ansel, but that''s okay...it''s an awesome shot. Love the detail and the rich contrast!', '2014-12-14 14:10:27.000000', NULL, 1),
(7292729, 1136598, 124982, '<td valign="top">Strikes me as a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=96574" rel="nofollow" target="_blank">Cuttooth</a> image? Incredibly beautiful detail and wonderful lighting!</td>', 'Strikes me as a  Cuttooth image? Incredibly beautiful detail and wonderful lighting!', '2014-12-14 14:11:27.000000', NULL, 1),
(7292732, 1136742, 124982, '<td valign="top">Lovely landscape, but I just cant tell where the focal point is. My eye floats all over  the frame, with no strong subject to rest on. Image seems a little soft too, lacks a little sharpness.</td>', 'Lovely landscape, but I just cant tell where the focal point is. My eye floats all over  the frame, with no strong subject to rest on. Image seems a little soft too, lacks a little sharpness.', '2014-12-14 14:12:53.000000', NULL, 1),
(7292733, 1136744, 100831, '<td valign="top">This has an edge to it that I really like...that foreground is almost other-worldly and I love the sloping ground behind it.  Well done.</td>', 'This has an edge to it that I really like...that foreground is almost other-worldly and I love the sloping ground behind it.  Well done.', '2014-12-14 14:13:00.000000', NULL, 1),
(7292734, 1136738, 124982, '<td valign="top">A little over-cooked with the processing -- some halos around the church.</td>', 'A little over-cooked with the processing -- some halos around the church.', '2014-12-14 14:13:28.000000', NULL, 1),
(7292735, 1136564, 124982, '<td valign="top">Hate the frame, but love the shot. Quite lovely lighting and contrast!</td>', 'Hate the frame, but love the shot. Quite lovely lighting and contrast!', '2014-12-14 14:13:52.000000', NULL, 1),
(7292736, 1136659, 124982, '<td valign="top">Quite gorgeous. Really appreciate this image...so serene and calm. Very sharp (maybe a little too much?) and clear -- big fan.</td>', 'Quite gorgeous. Really appreciate this image...so serene and calm. Very sharp (maybe a little too much?) and clear -- big fan.', '2014-12-14 14:14:40.000000', NULL, 1),
(7292737, 1136657, 124982, '<td valign="top">And a beautiful garden at that! What a view. Lovely soft processing.</td>', 'And a beautiful garden at that! What a view. Lovely soft processing.', '2014-12-14 14:15:27.000000', NULL, 1),
(7292738, 1136595, 124982, '<td valign="top">Beautiful scene, but lacks an exciting/powerful focal point. My eye flits over the frame, but find nothing to rest on.</td>', 'Beautiful scene, but lacks an exciting/powerful focal point. My eye flits over the frame, but find nothing to rest on.', '2014-12-14 14:16:46.000000', NULL, 1),
(7292739, 1136769, 124982, '<td valign="top">Ah....could stare at this forever! Would love to have something like this hanging on my wall!</td>', 'Ah....could stare at this forever! Would love to have something like this hanging on my wall!', '2014-12-14 14:17:13.000000', NULL, 1),
(7292740, 1136680, 124982, '<td valign="top">What beautiful, contemplative image. Very rich contrast and lighting. Incredible serene!</td>', 'What beautiful, contemplative image. Very rich contrast and lighting. Incredible serene!', '2014-12-14 14:18:11.000000', NULL, 1),
(7292741, 1136734, 124982, '<td valign="top">Bizarre composition, but quite lovely. Very nicely processed -- almost <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/user_id/30861.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/user_id/30861.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/user_id/30861.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30861" rel="nofollow" target="_blank">Bear_Music</a>-like.</td>', 'Bizarre composition, but quite lovely. Very nicely processed -- almost  Bear_Music-like.', '2014-12-14 14:19:12.000000', NULL, 1),
(7292768, 1136780, 109363, '<td valign="top">might have cloned out the power lines</td>', 'might have cloned out the power lines', '2014-12-14 16:22:11.000000', NULL, 1),
(7292769, 1136715, 109363, '<td valign="top">like the subject, but something funky with the structure/sharpening in the background</td>', 'like the subject, but something funky with the structure/sharpening in the background', '2014-12-14 16:24:46.000000', NULL, 1),
(7292770, 1136595, 109363, '<td valign="top">beautiful, except for the pine tree on left, which looks over-structured or over-sharpened.</td>', 'beautiful, except for the pine tree on left, which looks over-structured or over-sharpened.', '2014-12-14 16:27:12.000000', NULL, 1),
(7292771, 1136704, 109363, '<td valign="top">looks over-structured.  coloring also a bit off-putting.</td>', 'looks over-structured.  coloring also a bit off-putting.', '2014-12-14 16:28:04.000000', NULL, 1),
(7292773, 1136739, 109363, '<td valign="top">might have cloned out the Christmas tree... detracts from the image, IMO</td>', 'might have cloned out the Christmas tree... detracts from the image, IMO', '2014-12-14 16:29:37.000000', NULL, 1),
(7292799, 1136595, 112739, '<td valign="top">Classic Adams. Deep dark sky, details in the shadows, clouds are spot on. Top 3 for sure.</td>', 'Classic Adams. Deep dark sky, details in the shadows, clouds are spot on. Top 3 for sure.', '2014-12-14 18:16:21.000000', NULL, 1),
(7292800, 1136710, 112739, '<td valign="top">Strong, direct composition.</td>', 'Strong, direct composition.', '2014-12-14 18:17:11.000000', NULL, 1),
(7292801, 1136657, 112739, '<td valign="top">This really has a Ansel feel. Great work.</td>', 'This really has a Ansel feel. Great work.', '2014-12-14 18:17:55.000000', NULL, 1),
(7292802, 1136738, 112739, '<td valign="top">Would like to see a darker sky, but overall, a very good Ansel image.</td>', 'Would like to see a darker sky, but overall, a very good Ansel image.', '2014-12-14 18:18:27.000000', NULL, 1),
(7292803, 1136680, 112739, '<td valign="top">Just love to see all the fine details and fine contrast. The snow exposure is perfect as is the rest of the image.</td>', 'Just love to see all the fine details and fine contrast. The snow exposure is perfect as is the rest of the image.', '2014-12-14 18:19:07.000000', NULL, 1),
(7292804, 1136760, 112739, '<td valign="top">I came extremely close to entering a color version entry, but changed my mind during the last 30 minutes. Now I sort of regret the decision. Hope this isn''t getting too many low votes because I think it is a good choice.</td>', 'I came extremely close to entering a color version entry, but changed my mind during the last 30 minutes. Now I sort of regret the decision. Hope this isn''t getting too many low votes because I think it is a good choice.', '2014-12-14 18:20:50.000000', NULL, 1),
(7292805, 1136598, 112739, '<td valign="top">Bumping this one. Love the fine details. Placement of the tree is quote perfect. Top 3.</td>', 'Bumping this one. Love the fine details. Placement of the tree is quote perfect. Top 3.', '2014-12-14 18:21:43.000000', NULL, 1),
(7292806, 1136659, 112739, '<td valign="top">Dramatic deep contrast makes this very special.</td>', 'Dramatic deep contrast makes this very special.', '2014-12-14 18:22:14.000000', NULL, 1),
(7292807, 1136671, 112739, '<td valign="top">Well done.</td>', 'Well done.', '2014-12-14 18:22:47.000000', NULL, 1),
(7292808, 1136734, 112739, '<td valign="top">Bumping.</td>', 'Bumping.', '2014-12-14 18:23:50.000000', NULL, 1),
