(7292810, 1136537, 112739, '<td valign="top">This has about as wide a DR as you can get I think. Deep deep darks and very light lights. That "S" curve on the side hill is pretty cool.</td>', 'This has about as wide a DR as you can get I think. Deep deep darks and very light lights. That "S" curve on the side hill is pretty cool.', '2014-12-14 18:25:25.000000', NULL, 1),
(7292811, 1136769, 112739, '<td valign="top">this one caught my attention right away. Not sure how Ansel it is, but I really like it.</td>', 'this one caught my attention right away. Not sure how Ansel it is, but I really like it.', '2014-12-14 18:26:00.000000', NULL, 1),
(7292812, 1136735, 112739, '<td valign="top">Not too much interest in the image as a whole, but I like the openness feel it has.</td>', 'Not too much interest in the image as a whole, but I like the openness feel it has.', '2014-12-14 18:27:04.000000', NULL, 1),
(7292813, 1136704, 112739, '<td valign="top">Interesting Duotone.</td>', 'Interesting Duotone.', '2014-12-14 18:27:29.000000', NULL, 1),
(7292814, 1136760, 8759, '<td valign="top">i love the silhouettes in the backgorund</td>', 'i love the silhouettes in the backgorund', '2014-12-14 18:28:07.000000', NULL, 1),
(7292815, 1136750, 112739, '<td valign="top">The dark fine details seem to be a little overdone, bit overall a good image.</td>', 'The dark fine details seem to be a little overdone, bit overall a good image.', '2014-12-14 18:28:09.000000', NULL, 1),
(7292816, 1136768, 112739, '<td valign="top">The composition seems a little cramped in to me. Love the perfectly exposed white snow.</td>', 'The composition seems a little cramped in to me. Love the perfectly exposed white snow.', '2014-12-14 18:29:17.000000', NULL, 1),
