(7292818, 1136766, 112739, '<td valign="top">Hard to see the lake. Maybe could have been closer, but maybe it is private land. Love that mtn range.</td>', 'Hard to see the lake. Maybe could have been closer, but maybe it is private land. Love that mtn range.', '2014-12-14 18:31:26.000000', NULL, 1),
(7292819, 1136781, 112739, '<td valign="top">Very intriguing composition. Looks like a forest in Florida.</td>', 'Very intriguing composition. Looks like a forest in Florida.', '2014-12-14 18:32:16.000000', NULL, 1),
(7292820, 1136720, 112739, '<td valign="top">I might have worked the sky a little darker, but this is really an interesting scene. The house boats really make this pretty cool.</td>', 'I might have worked the sky a little darker, but this is really an interesting scene. The house boats really make this pretty cool.', '2014-12-14 18:33:49.000000', NULL, 1),
(7292821, 1136761, 112739, '<td valign="top">Very deep contrasts. The river and leafless trees really work well.</td>', 'Very deep contrasts. The river and leafless trees really work well.', '2014-12-14 18:35:09.000000', NULL, 1),
(7292823, 1136767, 112739, '<td valign="top">Very good macro with lots of details. I might have cropped out the bottom leaf to leave us with just the main leaf to enjoy.</td>', 'Very good macro with lots of details. I might have cropped out the bottom leaf to leave us with just the main leaf to enjoy.', '2014-12-14 18:36:36.000000', NULL, 1),
(7292824, 1136739, 112739, '<td valign="top">Cool. A tree on the bow! I would think it was a Christmas tree, but not really sure.</td>', 'Cool. A tree on the bow! I would think it was a Christmas tree, but not really sure.', '2014-12-14 18:37:41.000000', NULL, 1),
(7292825, 1136763, 112739, '<td valign="top">Wow, take the highway out of the frame and you have a really great shot here.</td>', 'Wow, take the highway out of the frame and you have a really great shot here.', '2014-12-14 18:38:33.000000', NULL, 1),
